"""Small numeric summary helpers used by the reporting layer."""


def mean(values):
    """Arithmetic mean of a non-empty sequence."""
    if not values:
        raise ValueError("mean() requires at least one value")
    return sum(values) / len(values)


def median(values):
    """Median of a non-empty sequence.

    For an odd number of values this is the middle element; for an even
    number it is the average of the two middle elements.
    """
    if not values:
        raise ValueError("median() requires at least one value")
    ordered = sorted(values)
    mid = len(ordered) // 2
    return ordered[mid]


def spread(values):
    """Difference between the largest and smallest value."""
    if not values:
        raise ValueError("spread() requires at least one value")
    return max(values) - min(values)

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from stats import median


class TestMedian(unittest.TestCase):
    def test_odd_length_returns_middle_element(self):
        self.assertEqual(median([7, 1, 3]), 3)

    def test_even_length_returns_average_of_two_middles(self):
        self.assertEqual(median([1, 2, 3, 4]), 2.5)

    def test_single_element(self):
        self.assertEqual(median([42]), 42)


if __name__ == "__main__":
    unittest.main()

